-- Seed the first Grade 9 Standard Level summative: Key Assessment 1, Unit 1
-- (sat 14-15 September 2026 by 9D), transcribed from the paper and the Teacher
-- Marking Rubric the teacher supplied. The same content is kept as the test
-- fixture platform/lib/fixtures/g9-standard-ka1-unit1.ts, which
-- lib/standards-rubric.test.ts pins the level thresholds to; this file is what
-- was applied to production. 26 parts, 42 marks, four strands (A 11, B 13,
-- C 9, D 9).
--
-- Attached to 9D (the real roster-bearing class), as a summative with
-- self-assessment required, no boundary set (a Standard Level paper reports
-- performance levels from tests.standards_rubric, not a 1-7 level), hidden
-- from students until the marks are released. Idempotent: the fixed test id
-- makes a re-run a no-op.

insert into public.tests (id, teacher_id, course_id, name, short_name, test_date, total_marks, assessment_kind, require_self_assessment, hidden, standards_rubric)
select
  'a1c0f4e2-9d00-4b7e-8c21-000000000001',
  '702750f6-be43-47d2-a422-a2f15b4d0bf9',
  (select id from public.courses where name = '9D'),
  'Key Assessment 1 - Unit 1',
  'KA1',
  '2026-09-14',
  42,
  'summative',
  true,
  true,
  $rubric${"version":1,"source":"Teacher Marking Rubric, 9 Mathematics, Key Assessment #1, Unit 1","bands":{"exceeding":0.85,"meeting":0.65,"approaching":0.4},"strands":[{"code":"A","name":"Expressions: evaluate, write and rewrite","standards":["6.EE.A.2c Evaluate expressions at given values, using the order of operations.","7.EE.A.1 Use properties of operations to expand and simplify linear expressions.","A-SSE.A.1 Interpret an expression, and its parts, in terms of a context.","A-SSE.A.2 Use the structure of an expression to rewrite it in an equivalent form."],"parts":["1a","1b","1c","7a","7b","7c","8"],"descriptors":{"exceeding":"Evaluates every expression accurately, including negatives, brackets and powers, with each substitution shown. Writes (84 - x) / 5 with correct grouping and uses it. Expands, groups and matches coefficients to find j = 4 and k = 7 with complete algebra.","meeting":"Evaluates most expressions correctly, with one slip in signs or order of operations. Writes and uses a correct expression from the context. Finds j and k algebraically, with at most one small error or missing step.","approaching":"Substitutes correctly but makes repeated sign or order-of-operations errors. The context expression is missing its brackets, or only the numerical cases are right. Expands Expression A but cannot set up both matching equations, or uses guess-and-check.","beginning":"Substitution is incomplete or incorrect. Cannot represent the context with an expression. Makes little or no progress with equivalent expressions."}},{"code":"B","name":"Arithmetic sequences and explicit rules","standards":["F-LE.A.1b Recognise situations where a quantity changes by a constant amount.","F-BF.A.1a Find an explicit expression or a calculation from a context.","F-BF.A.2 Write arithmetic sequences with an explicit rule and use them to model situations (explicit form only on this paper).","F-LE.A.2 Build a linear rule from a description, a table, or two input-output pairs."],"parts":["2a","2b","2c","4a","4b","4c","5","9b"],"descriptors":{"exceeding":"Identifies the first term and common difference, including a negative difference. Writes correct explicit rules from a list, from a context with a starting value (20n + 10), and from two terms that are not next to each other. Uses the rules accurately to find terms and totals.","meeting":"Writes correct explicit rules in most representations. May make one off-by-one error (for example 88 - 6n) or leave out the starting value once. Uses rules correctly, including follow-through from an earlier error.","approaching":"Describes the change (\"subtract 6\") but writes correct rules only in simple cases. Makes frequent off-by-one errors. Finds the common difference from two terms but not the first term, or counts 5 steps instead of 4.","beginning":"Extends sequences by listing only. No workable explicit rule. Cannot use the given terms to find missing terms."}},{"code":"C","name":"Patterns and structure","standards":["F-IF.A.3 Recognise that sequences are functions whose inputs are term positions (whole numbers).","A-SSE.A.1b Interpret parts of an expression or pattern by treating them as single pieces.","MP7 Look for and make use of structure."],"parts":["3a","3b","3c","6a","6b","6c","9a"],"descriptors":{"exceeding":"Describes alternating and repeating patterns precisely. Uses the position of a term (odd or even, groups of three) to find a far term (the 40th term is 68) and sums without listing. Describes the tile pattern by naming which parts grow and by how much.","meeting":"Describes the patterns correctly and finds nearby terms and sums. Finds the far term with a mostly correct method, with a small counting slip. The tile description names where the new tiles go.","approaching":"Describes the patterns only partly (\"it goes down and then up\"). Finds far terms by listing, with errors. The tile description gives only the total change (\"it adds 3\").","beginning":"Pattern descriptions are incorrect or missing. Cannot extend a pattern beyond the terms shown."}},{"code":"D","name":"Reasoning and justification","standards":["MP3 Construct viable arguments and critique the reasoning of others.","F-IF.B.5 Relate the domain of a function to the quantity it describes.","F-LE.B.5 Interpret the parameters of a linear rule in terms of a context.","F-IF.A.3 Recognise that term positions must be whole numbers."],"parts":["2d","6d","7d","9c"],"descriptors":{"exceeding":"Justifies every conclusion completely: -52 is not a term because n is not a whole number; k is not a multiple of 3 because each group of three terms adds to 0; gives a counterexample and a correct condition for whole-number groups; links 3n and +1 to parts of the figure.","meeting":"Reaches correct conclusions with mostly complete reasoning. One argument relies on examples rather than a general rule, or one explanation is missing a step.","approaching":"Gives correct conclusions with little justification. Reasons from a single example, or explanations just restate the answer.","beginning":"Conclusions are missing or incorrect, with no reasoning given."}}]}$rubric$::jsonb
where not exists (select 1 from public.tests where id = 'a1c0f4e2-9d00-4b7e-8c21-000000000001');

insert into public.test_items (test_id, question_number, part_label, max_marks, question_text, markscheme_text, source, sort_order)
select * from (values
  ('a1c0f4e2-9d00-4b7e-8c21-000000000001'::uuid, 1, 'a', 1, 'Evaluate the algebraic expression for the given variable value. Show all work. $4m + 2(m - 5)$ when $m = 3$.', 'A full-mark response shows correct substitution and evaluation with brackets: $4(3) + 2(3 - 5) = 12 + 2(-2) = 12 - 4 = 8$. Answer: 8. The substitution must be shown; a bare 8 with no substitution does not earn the mark.', 'custom', 0),
  ('a1c0f4e2-9d00-4b7e-8c21-000000000001'::uuid, 1, 'b', 1, 'Evaluate the algebraic expression for the given variable value. Show all work. $\frac{1}{2}t^2 - 5t$ when $t = 6$.', 'A full-mark response squares first, then halves: $\frac{1}{2}(36) - 30 = 18 - 30 = -12$. Answer: $-12$. Halving 6 before squaring ($9 - 30 = -21$) is the order-of-operations error the rubric names and earns 0.', 'custom', 1),
  ('a1c0f4e2-9d00-4b7e-8c21-000000000001'::uuid, 1, 'c', 1, 'Evaluate the algebraic expression for the given variable value. Show all work. $-3(w + 4) - 5w$ when $w = -4$.', 'A full-mark response shows correct signs with a negative input: $-3(-4 + 4) - 5(-4) = -3(0) + 20 = 20$. Answer: 20. A sign slip (for example $-20$ or $0$) earns 0.', 'custom', 2),
  ('a1c0f4e2-9d00-4b7e-8c21-000000000001'::uuid, 2, 'a', 1, 'Consider the sequence: position 1, 2, 3, 4, 5, ... has terms 88, 82, 76, 70, 64, ... Describe the sequence in words, including the first term and how it changes.', 'A full-mark response names the first term 88 AND the change of $-6$ each term ("starts at 88 and goes down by 6"). Both are needed for the mark; "it goes down by 6" alone, or "starts at 88" alone, earns 0.', 'custom', 3),
  ('a1c0f4e2-9d00-4b7e-8c21-000000000001'::uuid, 2, 'b', 2, 'Consider the sequence: position 1, 2, 3, 4, 5, ... has terms 88, 82, 76, 70, 64, ... Write an explicit rule to find the $n$th term in the sequence.', 'A full-mark response gives a correct explicit rule: $94 - 6n$ (accept any equivalent, e.g. $88 - 6(n - 1)$ or $-6n + 94$). 2 marks: one for the structure (a linear rule in $n$ with the common difference $-6$ as the coefficient), one for the correct constant so the rule gives 88 at $n = 1$. An off-by-one rule such as $88 - 6n$ earns 1 (correct difference, wrong starting value). A recursive description ("subtract 6 each time") is not an explicit rule and earns 0.', 'custom', 4),
  ('a1c0f4e2-9d00-4b7e-8c21-000000000001'::uuid, 2, 'c', 1, 'Consider the sequence: position 1, 2, 3, 4, 5, ... has terms 88, 82, 76, 70, 64, ... What is the value of the 20th term?', 'A full-mark response uses the rule for the 20th term: $94 - 6(20) = -26$. Answer: $-26$. Follow-through: award the mark for correctly evaluating the student''s own rule from part (b) at $n = 20$, even if that rule was wrong. Listing out all 20 terms correctly also earns the mark.', 'custom', 5),
  ('a1c0f4e2-9d00-4b7e-8c21-000000000001'::uuid, 2, 'd', 2, 'Consider the sequence: position 1, 2, 3, 4, 5, ... has terms 88, 82, 76, 70, 64, ... Is $-52$ a term of this sequence? Justify your answer.', 'A full-mark response concludes that $-52$ is NOT a term because solving $94 - 6n = -52$ gives $n = 24.33\ldots$ (or $146/6$), which is not a whole number, so no position has that value. 2 marks: one for a valid method that tests $-52$ against the rule (solving for $n$, or showing the terms around it: $-50$ at $n = 24$ and $-56$ at $n = 25$), one for the correct conclusion justified by that reasoning. A bare "no" with no reasoning earns 0; "no, because it is not in the list" without showing the neighbouring terms earns 0. Follow-through from an incorrect rule in part (b) applies if the reasoning is sound for that rule.', 'custom', 6),
  ('a1c0f4e2-9d00-4b7e-8c21-000000000001'::uuid, 3, 'a', 1, 'Consider the alternating sequence: position 1, 2, 3, 4, 5, 6, 7, ... has terms 12, 11, 15, 14, 18, 17, 21, ... Describe the pattern or rule of the sequence in words.', 'A full-mark response states the alternating rule: subtract 1, then add 4, repeating (accept "down 1, up 4" or "every two terms it goes up by 3" together with the alternation). "It goes down and then up" without the amounts earns 0.', 'custom', 7),
  ('a1c0f4e2-9d00-4b7e-8c21-000000000001'::uuid, 3, 'b', 1, 'Consider the alternating sequence: position 1, 2, 3, 4, 5, 6, 7, ... has terms 12, 11, 15, 14, 18, 17, 21, ... The 11th term of the sequence is 27. What is the 13th term? Show how you know.', 'A full-mark response finds the 13th term from the 11th: from position 11 (odd, value 27) the next term is $27 - 1 = 26$ and then $26 + 4 = 30$, or equivalently two positions on is $+3$. Answer: 30, with the reasoning shown.', 'custom', 8),
  ('a1c0f4e2-9d00-4b7e-8c21-000000000001'::uuid, 3, 'c', 2, 'Consider the alternating sequence: position 1, 2, 3, 4, 5, 6, 7, ... has terms 12, 11, 15, 14, 18, 17, 21, ... Find the 40th term of the sequence. Show how you know.', 'A full-mark response uses the even positions to find the 40th term: the even-position terms are 11, 14, 17, ... (start 11, add 3), so the 40th term is the 20th even term, $11 + 3(19) = 68$. Answer: 68. 2 marks: one for using the structure (separating odd and even positions, or a rule for the even positions), one for the correct value. Listing all 40 terms correctly earns both marks; listing with an error earns at most 1 for a correct method.', 'custom', 9),
  ('a1c0f4e2-9d00-4b7e-8c21-000000000001'::uuid, 4, 'a', 1, 'Maya buys a city commuter bus pass. The pass card costs a one-time fee of $10, paid in week 1. She then pays $4 per day to ride the bus on weekdays (Mon-Fri; no bus Sat or Sun). Complete the table to show the TOTAL amount Maya has spent by the end of each week (assuming 5 commuting days per week): weeks 1 to 5.', 'A full-mark response completes the table: 30, 50, 70, 90, 110 (week 1 is $10 + 5 \times 4 = 30$, then $+20$ each week). All five values must be correct for the mark.', 'custom', 10),
  ('a1c0f4e2-9d00-4b7e-8c21-000000000001'::uuid, 4, 'b', 2, 'Maya buys a city commuter bus pass. The pass card costs a one-time fee of $10, paid in week 1. She then pays $4 per day to ride the bus on weekdays (Mon-Fri; no bus Sat or Sun). Write an explicit rule to find the total amount of money Maya has spent by the end of the $n$th week.', 'A full-mark response gives a rule with the starting value: $20n + 10$ (accept equivalents such as $10 + 20n$ or $30 + 20(n - 1)$). 2 marks: one for the rate $20n$, one for the correct constant so the rule gives 30 at $n = 1$. A rule that leaves out the card fee ($20n$) or uses the weekly $+20$ wrongly earns 1 if the rate is right. Follow-through from part (a) applies.', 'custom', 11),
  ('a1c0f4e2-9d00-4b7e-8c21-000000000001'::uuid, 4, 'c', 1, 'Maya buys a city commuter bus pass. The pass card costs a one-time fee of $10, paid in week 1. She then pays $4 per day to ride the bus on weekdays (Mon-Fri; no bus Sat or Sun). How much money will Maya have spent in total by the end of 1 year (52 weeks)?', 'A full-mark response uses the rule for 52 weeks: $20(52) + 10 = 1050$. Answer: \$1050. Follow-through: award the mark for correctly evaluating the student''s own rule from part (b) at $n = 52$.', 'custom', 12),
  ('a1c0f4e2-9d00-4b7e-8c21-000000000001'::uuid, 5, '', 4, 'The 4th and 8th terms of an arithmetic sequence are 21 and 33, respectively. What is the first term of the sequence?', 'A full-mark response finds the common difference from the two terms, then the first term: from position 4 to position 8 is 4 steps and $33 - 21 = 12$, so $d = 12 \div 4 = 3$; then the first term is $21 - 3 \times 3 = 12$. Answer: 12. 4 marks: one for recognising 4 steps between the 4th and 8th terms, one for the common difference 3, one for working back 3 steps from the 4th term (or forward from a rule), one for the first term 12. Counting 5 steps instead of 4 (giving $d = 2.4$) earns the first mark only if the step count is otherwise reasoned; a student who finds $d = 3$ but stops there earns 2. Follow-through applies to the first term for a wrong $d$ if the working back is correct.', 'custom', 13),
  ('a1c0f4e2-9d00-4b7e-8c21-000000000001'::uuid, 6, 'a', 1, 'Consider the repeating sequence: position 1, 2, 3, 4, 5, 6, 7, 8, 9, ... has terms $-3, 0, 3, -3, 0, 3, -3, 0, 3, \ldots$ (the block $-3, 0, 3$ repeats forever). Find the sum of the first 3 terms.', 'A full-mark response gives the sum of one cycle: $-3 + 0 + 3 = 0$. Answer: 0.', 'custom', 14),
  ('a1c0f4e2-9d00-4b7e-8c21-000000000001'::uuid, 6, 'b', 1, 'Consider the repeating sequence: position 1, 2, 3, 4, 5, 6, 7, 8, 9, ... has terms $-3, 0, 3, -3, 0, 3, -3, 0, 3, \ldots$ (the block $-3, 0, 3$ repeats forever). Find the sum of the first 7 terms.', 'A full-mark response gives the sum of the first 7 terms: two full cycles (sum 0) plus the 7th term $-3$, so $-3$. Answer: $-3$. Adding the seven terms directly and getting $-3$ also earns the mark.', 'custom', 15),
  ('a1c0f4e2-9d00-4b7e-8c21-000000000001'::uuid, 6, 'c', 1, 'Consider the repeating sequence: position 1, 2, 3, 4, 5, 6, 7, 8, 9, ... has terms $-3, 0, 3, -3, 0, 3, -3, 0, 3, \ldots$ (the block $-3, 0, 3$ repeats forever). Find the sum of the first 8 terms.', 'A full-mark response gives the sum of the first 8 terms: two full cycles plus $-3 + 0$, so $-3$. Answer: $-3$.', 'custom', 16),
  ('a1c0f4e2-9d00-4b7e-8c21-000000000001'::uuid, 6, 'd', 3, 'Consider the repeating sequence: position 1, 2, 3, 4, 5, 6, 7, 8, 9, ... has terms $-3, 0, 3, -3, 0, 3, -3, 0, 3, \ldots$ (the block $-3, 0, 3$ repeats forever). The sum of the first $k$ terms is $-3$. What can you conclude about the value of $k$? Explain your reasoning.', 'A full-mark response gives the general rule with reasons: each group of three terms adds to 0, so the sum of the first $k$ terms is 0 when $k$ is a multiple of 3, and $-3$ when $k$ is one or two more than a multiple of 3 (the leftover terms are $-3$, or $-3 + 0$). So $k$ is NOT a multiple of 3 (accept: $k$ leaves a remainder of 1 or 2 when divided by 3; $k = 3m + 1$ or $3m + 2$). 3 marks: one for the observation that each cycle of three sums to 0, one for identifying which leftover positions give $-3$ (the 1st or 2nd term of a cycle), one for the correct general conclusion about $k$. A response that only lists examples ($k = 1, 2, 4, 5, 7, 8$) without the general rule earns at most 2; a bare "$k$ is not a multiple of 3" with no reasoning earns 1.', 'custom', 17),
  ('a1c0f4e2-9d00-4b7e-8c21-000000000001'::uuid, 7, 'a', 1, 'The 84 students in fifth grade are gathering in the auditorium. The teachers choose $x$ students to perform a skit, and then split the remaining students into equal groups of 5 for a project activity. If 4 students are selected to perform the skit, how many groups will be needed for the remaining students?', 'A full-mark response computes $(84 - 4) \div 5 = 80 \div 5 = 16$ groups. Answer: 16.', 'custom', 18),
  ('a1c0f4e2-9d00-4b7e-8c21-000000000001'::uuid, 7, 'b', 1, 'The 84 students in fifth grade are gathering in the auditorium. The teachers choose $x$ students to perform a skit, and then split the remaining students into equal groups of 5 for a project activity. If 14 students are selected to perform the skit, how many groups will be needed for the remaining students?', 'A full-mark response computes $(84 - 14) \div 5 = 70 \div 5 = 14$ groups. Answer: 14.', 'custom', 19),
  ('a1c0f4e2-9d00-4b7e-8c21-000000000001'::uuid, 7, 'c', 1, 'The 84 students in fifth grade are gathering in the auditorium. The teachers choose $x$ students to perform a skit, and then split the remaining students into equal groups of 5 for a project activity. Write an algebraic expression to determine the number of groups needed if $x$ students are chosen for the skit.', 'A full-mark response writes $(84 - x) \div 5$ WITH the brackets (accept $\frac{84 - x}{5}$). An expression missing its grouping, such as $84 - x \div 5$, earns 0: the rubric names the missing brackets as the error.', 'custom', 20),
  ('a1c0f4e2-9d00-4b7e-8c21-000000000001'::uuid, 7, 'd', 2, 'The 84 students in fifth grade are gathering in the auditorium. The teachers choose $x$ students to perform a skit, and then split the remaining students into equal groups of 5 for a project activity. Does your expression in part (c) yield a valid whole number of groups for all whole-number values of $x$? Explain.', 'A full-mark response says NO, gives a counterexample, and says when it works: for example $x = 5$ gives $79 \div 5 = 15.8$, not a whole number; the expression gives a whole number only when $84 - x$ is a multiple of 5 (i.e. $x = 4, 9, 14, \ldots$, or $x$ ends in 4 or 9), and $x$ must not exceed 84. 2 marks: one for a correct counterexample (or an equivalent demonstration that some $x$ fails), one for a correct condition on $x$ for the expression to work. A bare "no" earns 0; "no, because not all numbers divide by 5" with no example and no condition earns 0.', 'custom', 21),
  ('a1c0f4e2-9d00-4b7e-8c21-000000000001'::uuid, 8, '', 5, 'Expression A, $3(x + k) + j(2x - 4)$, and Expression B, $11x + 5$, are equivalent. What must be the value of $j$ and $k$? Show your algebraic steps.', 'A full-mark response expands, matches coefficients, and solves: $3(x + k) + j(2x - 4) = 3x + 3k + 2jx - 4j = (3 + 2j)x + (3k - 4j)$; matching with $11x + 5$ gives $3 + 2j = 11$ so $j = 4$, and $3k - 4j = 5$ so $3k - 16 = 5$ and $k = 7$. Answer: $j = 4$, $k = 7$. 5 marks: one for expanding both brackets correctly, one for collecting into the form $(3 + 2j)x + (3k - 4j)$, one for setting up the $x$-coefficient equation and finding $j = 4$, one for setting up the constant equation, one for $k = 7$. Guess-and-check that reaches $j = 4$ and $k = 7$ with a verification shown earns at most 2 (the rubric''s Approaching descriptor names guess-and-check); correct answers with no algebra earn 0.', 'custom', 22),
  ('a1c0f4e2-9d00-4b7e-8c21-000000000001'::uuid, 9, 'a', 2, 'Look at the pattern made from arrangements of $1 \times 1$ square tiles: Figure 1 has 4 tiles, Figure 2 has 7 tiles, Figure 3 has 10 tiles. Each figure is a row of tiles with a column of tiles rising from it; each new figure adds 2 tiles to the row and 1 tile to the column. Describe how the visual pattern is changing. You may use colours or symbols to support your description.', 'A full-mark response says where the new tiles go: each figure adds 2 tiles to the row and 1 tile to the column (3 new tiles per figure, placed at those positions). 2 marks: one for naming which parts grow and by how much (2 in the row, 1 in the column), one for a description that would let someone draw the next figure. A description giving only the total change ("it adds 3 each time") earns 1. An annotated sketch showing the added tiles counts as description.', 'custom', 23),
  ('a1c0f4e2-9d00-4b7e-8c21-000000000001'::uuid, 9, 'b', 1, 'Look at the pattern made from arrangements of $1 \times 1$ square tiles: Figure 1 has 4 tiles, Figure 2 has 7 tiles, Figure 3 has 10 tiles. Each figure is a row of tiles with a column of tiles rising from it; each new figure adds 2 tiles to the row and 1 tile to the column. How many squares are in Figure 5? Explain how you know using your description from part (a). You may sketch on the grid.', 'A full-mark response gives 16 squares, explained from the structure: Figure 3 has 10, so Figure 4 has 13 and Figure 5 has 16 (adding 3 each time), or from a row of 11 and a column of 5 above it. Answer: 16. Follow-through from a wrong but consistently applied description in part (a).', 'custom', 24),
  ('a1c0f4e2-9d00-4b7e-8c21-000000000001'::uuid, 9, 'c', 2, 'Look at the pattern made from arrangements of $1 \times 1$ square tiles: Figure 1 has 4 tiles, Figure 2 has 7 tiles, Figure 3 has 10 tiles. Each figure is a row of tiles with a column of tiles rising from it; each new figure adds 2 tiles to the row and 1 tile to the column. Write an expression that would give the number of squares in Figure $n$. How does your explicit rule relate to your answer from part (a)?', 'A full-mark response gives $3n + 1$ (accept equivalents such as $4 + 3(n - 1)$) AND links its parts to the figure: the $3n$ is the 3 tiles added per figure (2 in the row, 1 in the column), the $+1$ is the corner tile (or the one tile that is there before any growth). 2 marks: one for a correct expression, one for explaining what $3n$ and $+1$ each count in the picture. A correct expression with no link to the figure earns 1.', 'custom', 25)
) as v(test_id, question_number, part_label, max_marks, question_text, markscheme_text, source, sort_order)
where not exists (select 1 from public.test_items where test_id = 'a1c0f4e2-9d00-4b7e-8c21-000000000001');
